import { MakeLogicType, actions, afterMount, connect, kea, listeners, path, reducers, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import { lemonToast } from 'lib/lemon-ui/LemonToast/LemonToast'
import { teamLogic } from 'scenes/teamLogic'

import type { TeamPublicType, TeamType } from '../../../../../frontend/src/types'
import {
    announcementTemplatesCreate,
    announcementTemplatesDestroy,
    announcementTemplatesList,
    announcementTemplatesUpdate,
} from '../../generated/api'
import type { AnnouncementTemplateApi } from '../../generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface announcementTemplatesLogicValues {
    currentTeam: TeamPublicType | TeamType | null // teamLogic
    templates: AnnouncementTemplateApi[]
    templatesLoading: boolean
    manageModalOpen: boolean
    editorOpen: boolean
    editingTemplateId: string | null
    formName: string
    formMessage: string
    saving: boolean
    saveDisabledReason: string | undefined
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface announcementTemplatesLogicActions {
    loadTemplates: () => any
    loadTemplatesFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadTemplatesSuccess: (
        templates: AnnouncementTemplateApi[],
        payload?: any
    ) => {
        templates: AnnouncementTemplateApi[]
        payload?: any
    }
    openManageModal: () => {
        value: true
    }
    closeManageModal: () => {
        value: true
    }
    openCreateEditor: (message: string) => {
        message: string
    }
    openEditEditor: (template: AnnouncementTemplateApi) => {
        template: AnnouncementTemplateApi
    }
    closeEditor: () => {
        value: true
    }
    setFormName: (name: string) => {
        name: string
    }
    setFormMessage: (message: string) => {
        message: string
    }
    setSaving: (saving: boolean) => {
        saving: boolean
    }
    saveTemplate: () => {
        value: true
    }
    deleteTemplate: (id: string) => {
        id: string
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface announcementTemplatesLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        saveDisabledReason: (formName: string, formMessage: string, saving: boolean) => string | undefined
    }
}

export type announcementTemplatesLogicType = MakeLogicType<
    announcementTemplatesLogicValues,
    announcementTemplatesLogicActions,
    Record<string, any>,
    announcementTemplatesLogicMeta
>

export const announcementTemplatesLogic = kea<announcementTemplatesLogicType>([
    path(['products', 'customer_analytics', 'frontend', 'components', 'Announcements', 'announcementTemplatesLogic']),
    connect(() => ({
        values: [teamLogic, ['currentTeam']],
    })),
    actions({
        openManageModal: true,
        closeManageModal: true,
        openCreateEditor: (message: string) => ({ message }),
        openEditEditor: (template: AnnouncementTemplateApi) => ({ template }),
        closeEditor: true,
        setFormName: (name: string) => ({ name }),
        setFormMessage: (message: string) => ({ message }),
        setSaving: (saving: boolean) => ({ saving }),
        saveTemplate: true,
        deleteTemplate: (id: string) => ({ id }),
    }),
    loaders(({ values }) => ({
        templates: [
            [] as AnnouncementTemplateApi[],
            {
                loadTemplates: async () => {
                    const response = await announcementTemplatesList(String(values.currentTeam?.id), { limit: 100 })
                    return response.results ?? []
                },
            },
        ],
    })),
    reducers({
        manageModalOpen: [false, { openManageModal: () => true, closeManageModal: () => false }],
        editorOpen: [
            false,
            {
                openCreateEditor: () => true,
                openEditEditor: () => true,
                closeEditor: () => false,
            },
        ],
        // Null while creating; the template id while editing an existing one.
        editingTemplateId: [
            null as string | null,
            {
                openCreateEditor: () => null,
                openEditEditor: (_state, { template }) => template.id,
                closeEditor: () => null,
            },
        ],
        formName: [
            '',
            {
                openCreateEditor: () => '',
                openEditEditor: (_state, { template }) => template.name,
                setFormName: (_state, { name }) => name,
            },
        ],
        formMessage: [
            '',
            {
                // "Save as template" seeds the body with the composer's current draft.
                openCreateEditor: (_state, { message }) => message,
                openEditEditor: (_state, { template }) => template.message,
                setFormMessage: (_state, { message }) => message,
            },
        ],
        saving: [false, { setSaving: (_state, { saving }) => saving }],
    }),
    selectors({
        saveDisabledReason: [
            (s) => [s.formName, s.formMessage, s.saving],
            (formName: string, formMessage: string, saving: boolean): string | undefined => {
                if (saving) {
                    return 'Saving…'
                }
                if (!formName.trim()) {
                    return 'Enter a name'
                }
                if (!formMessage.trim()) {
                    return 'Enter a message'
                }
                return undefined
            },
        ],
    }),
    listeners(({ values, actions }) => ({
        saveTemplate: async () => {
            // Guard against double-submission while a save is in flight.
            if (values.saving || values.saveDisabledReason) {
                return
            }
            actions.setSaving(true)
            const teamId = String(values.currentTeam?.id)
            const body = { name: values.formName.trim(), message: values.formMessage.trim() }
            try {
                if (values.editingTemplateId) {
                    await announcementTemplatesUpdate(teamId, values.editingTemplateId, body)
                    lemonToast.success('Template updated')
                } else {
                    await announcementTemplatesCreate(teamId, body)
                    lemonToast.success('Template saved')
                }
                actions.closeEditor()
                actions.loadTemplates()
            } catch {
                lemonToast.error('Could not save template. The name may already be in use.')
            } finally {
                actions.setSaving(false)
            }
        },
        deleteTemplate: async ({ id }) => {
            try {
                await announcementTemplatesDestroy(String(values.currentTeam?.id), id)
                lemonToast.success('Template deleted')
                actions.loadTemplates()
            } catch {
                lemonToast.error('Failed to delete template')
            }
        },
    })),
    afterMount(({ actions }) => {
        actions.loadTemplates()
    }),
])
